package com.nigson.commerce.reward;
import java.math.*;import java.sql.Timestamp;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.platform.AuditWriter;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import tools.jackson.databind.JsonNode;
/** Deterministic reward projections from independently verified local order/refund facts. */
public final class JdbcRewardOperations implements RewardOperations {
 private final JdbcTemplate jdbc;private final AuditWriter audit;private final Clock clock;
 public JdbcRewardOperations(JdbcTemplate jdbc,AuditWriter audit,Clock clock){this.jdbc=jdbc;this.audit=audit;this.clock=clock;}
 private void tx(){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");}
 private JsonNode json(String value){try{return EventCodec.JSON.readTree(value);}catch(Exception e){throw RewardValues.rule();}}
 private BigDecimal amount(JsonNode n,String key,boolean zero){if(!n.path(key).isString())throw RewardValues.rule();return zero?RewardValues.nonnegative(n.path(key).asString(),2):RewardValues.amount(n.path(key).asString(),2);}
 private int integer(JsonNode n,String key,int min,int max){if(!n.path(key).isIntegralNumber()||!n.path(key).canConvertToInt())throw RewardValues.rule();int v=n.path(key).intValue();if(v<min||v>max)throw RewardValues.rule();return v;}
 @Override public void orderSettled(UUID order,UUID correlation){tx();var os=jdbc.query("SELECT o.party_id,o.market_id,o.organization_id,o.currency_code,o.subtotal-o.discount_total AS spend,t.settled_at,m.code FROM commerce.sales_order o JOIN commerce.market m ON m.id=o.market_id JOIN commerce.payment_attempt a ON a.order_id=o.id AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL JOIN commerce.payment_transaction t ON t.attempt_id=a.id AND t.provider_status='success' WHERE o.id=? AND o.payment_status='PAID' ORDER BY t.settled_at DESC LIMIT 1",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(4),r.getBigDecimal(5),r.getTimestamp(6).toInstant(),r.getString(7)},order);if(os.size()!=1)return;var o=os.getFirst();UUID party=(UUID)o[0],market=(UUID)o[1],organization=(UUID)o[2];String currency=(String)o[3];BigDecimal spend=(BigDecimal)o[4];Instant settled=(Instant)o[5];if(!"NG".equals(o[6])||!"NGN".equals(currency))return;
  var attributions=jdbc.query("SELECT a.id,a.referrer_party_id,a.rule_id,r.parameters::text,r.market_id FROM commerce.referral_attribution a JOIN commerce.promotion_rule r ON r.id=a.rule_id WHERE a.referred_party_id=? AND a.state='ATTRIBUTED' AND r.kind='REFERRAL' ORDER BY a.id FOR UPDATE OF a,r",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(4),r.getObject(5,UUID.class)},party);for(Object[] a:attributions)referral(order,correlation,party,market,currency,spend,settled,a);
  var rules=jdbc.query("SELECT r.id,r.parameters::text,r.eligibility::text,r.market_id FROM commerce.promotion_rule r JOIN commerce.market m ON m.id=r.market_id WHERE r.kind='SPEND_REWARD' AND r.enabled AND r.starts_at<=? AND r.ends_at>? AND m.enabled AND m.code='NG' ORDER BY r.id FOR SHARE OF r,m",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getObject(4,UUID.class)},Timestamp.from(settled),Timestamp.from(settled));for(Object[] r:rules){if(!market.equals(r[3]))continue;JsonNode p=json((String)r[1]);RewardValues.exact(p,Set.of("schemaVersion","threshold","rewardAmount","maximumRewardPerOrder","holdDays","expiresDays","refundMode"));if(!p.path("schemaVersion").isIntegralNumber()||p.path("schemaVersion").asInt()!=1||!Set.of("PROPORTIONAL","FULL_ON_ANY_REFUND").contains(p.path("refundMode").asString()))throw RewardValues.rule();BigDecimal threshold=amount(p,"threshold",false),reward=amount(p,"rewardAmount",false).min(amount(p,"maximumRewardPerOrder",false));int hold=integer(p,"holdDays",0,365),expires=integer(p,"expiresDays",1,3650);Eligibility eligibility=eligibility(json((String)r[2]));BigDecimal eligibleSpend=eligibleSpend(order,party,organization,settled,eligibility);if(eligibleSpend.compareTo(threshold)<0||reward.signum()==0)continue;append(order,correlation,party,(UUID)r[0],reward,currency,"spend:"+order+":"+r[0],settled.plusSeconds(hold*86400L),expires);}}

 private record Eligibility(String segment,Set<UUID> products,Set<UUID> categories,BigDecimal minimumSpend,BigDecimal minimumQuantity,boolean firstOnly){}
 private Eligibility eligibility(JsonNode n){RewardValues.exact(n,Set.of("schemaVersion","segment","productIds","categoryIds","minimumSpend","minimumQuantity","firstSettledPurchaseOnly"));if(!n.path("schemaVersion").isIntegralNumber()||n.path("schemaVersion").asInt()!=1||!Set.of("ANY","RETAIL","DISTRIBUTOR").contains(n.path("segment").asString())||!n.path("productIds").isArray()||!n.path("categoryIds").isArray()||!n.path("firstSettledPurchaseOnly").isBoolean())throw RewardValues.rule();Set<UUID> products=uuidSet(n.path("productIds")),categories=uuidSet(n.path("categoryIds"));BigDecimal minimumSpend=nullableAmount(n.path("minimumSpend")),minimumQuantity=nullableQuantity(n.path("minimumQuantity"));return new Eligibility(n.path("segment").asString(),products,categories,minimumSpend,minimumQuantity,n.path("firstSettledPurchaseOnly").asBoolean());}
 private Set<UUID> uuidSet(JsonNode n){Set<UUID> values=new HashSet<>();for(JsonNode v:n){if(!v.isString())throw RewardValues.rule();try{if(!values.add(UUID.fromString(v.asString())))throw RewardValues.rule();}catch(IllegalArgumentException bad){throw RewardValues.rule();}}return Set.copyOf(values);}
 private BigDecimal nullableAmount(JsonNode n){if(n.isNull())return null;if(!n.isString())throw RewardValues.rule();return RewardValues.nonnegative(n.asString(),2);}
 private BigDecimal nullableQuantity(JsonNode n){if(n.isNull())return null;if(!n.isString())throw RewardValues.rule();try{BigDecimal value=new BigDecimal(n.asString());if(!value.toPlainString().equals(n.asString())||value.signum()<0||value.scale()>3||value.precision()>20)throw RewardValues.rule();return value;}catch(NumberFormatException bad){throw RewardValues.rule();}}
 private BigDecimal eligibleSpend(UUID order,UUID party,UUID organization,Instant settled,Eligibility rule){if((rule.segment().equals("RETAIL")&&organization!=null)||(rule.segment().equals("DISTRIBUTOR")&&organization==null))return BigDecimal.ZERO;if(rule.firstOnly()){Boolean prior=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order o JOIN commerce.payment_attempt a ON a.order_id=o.id AND a.state='SUCCEEDED' AND a.verified_at IS NOT NULL JOIN commerce.payment_transaction t ON t.attempt_id=a.id AND t.provider_status='success' WHERE o.party_id=? AND o.id<>? AND t.settled_at<?)",Boolean.class,party,order,Timestamp.from(settled));if(Boolean.TRUE.equals(prior))return BigDecimal.ZERO;}var lines=jdbc.query("SELECT ol.quantity,ol.line_total-ol.tax_amount,s.product_id FROM commerce.order_line ol JOIN commerce.sku s ON s.id=ol.sku_id WHERE ol.order_id=? ORDER BY ol.id",(r,n)->new Object[]{r.getBigDecimal(1),r.getBigDecimal(2),r.getObject(3,UUID.class)},order);if(lines.size()>100)throw RewardValues.rule();BigDecimal total=BigDecimal.ZERO,quantity=BigDecimal.ZERO;for(Object[] line:lines){UUID product=(UUID)line[2];if(!rule.products().isEmpty()&&!rule.products().contains(product))continue;if(!rule.categories().isEmpty()){List<UUID> found=jdbc.query("SELECT category_id FROM commerce.product_category WHERE product_id=?",(r,n)->r.getObject(1,UUID.class),product);if(Collections.disjoint(rule.categories(),found))continue;}total=total.add((BigDecimal)line[1]);quantity=quantity.add((BigDecimal)line[0]);}if(rule.minimumSpend()!=null&&total.compareTo(rule.minimumSpend())<0)return BigDecimal.ZERO;if(rule.minimumQuantity()!=null&&quantity.compareTo(rule.minimumQuantity())<0)return BigDecimal.ZERO;return total;}
 private void referral(UUID order,UUID correlation,UUID party,UUID market,String currency,BigDecimal spend,Instant settled,Object[] a){UUID id=(UUID)a[0],referrer=(UUID)a[1],rule=(UUID)a[2];if(!market.equals(a[4])){state(id,order,"INELIGIBLE",null);return;}JsonNode p=json((String)a[3]);RewardValues.exact(p,Set.of("schemaVersion","minimumSettledSpend","referrerReward","referredReward","holdDays","expiresDays","maximumRewardsPerReferrer","refundMode"));if(!p.path("schemaVersion").isIntegralNumber()||p.path("schemaVersion").asInt()!=1||!Set.of("PROPORTIONAL","FULL_ON_ANY_REFUND").contains(p.path("refundMode").asString()))throw RewardValues.rule();BigDecimal minimum=amount(p,"minimumSettledSpend",true),referrerReward=amount(p,"referrerReward",false),referredReward=amount(p,"referredReward",true);int hold=integer(p,"holdDays",0,365),expires=integer(p,"expiresDays",1,3650),max=integer(p,"maximumRewardsPerReferrer",1,Integer.MAX_VALUE);if(spend.compareTo(minimum)<0){state(id,order,"INELIGIBLE",null);return;}jdbc.query("SELECT id FROM commerce.party WHERE id=? FOR UPDATE",(r,n)->r.getObject(1,UUID.class),referrer);Integer issued=jdbc.queryForObject("SELECT count(*) FROM commerce.reward_entry WHERE party_id=? AND business_key LIKE 'referral:%:REFERRER'",Integer.class,referrer);if(issued!=null&&issued>=max){state(id,order,"INELIGIBLE",null);return;}Instant available=settled.plusSeconds(hold*86400L);append(order,correlation,referrer,rule,referrerReward,currency,"referral:"+id+":REFERRER",available,expires);if(referredReward.signum()>0)append(order,correlation,party,rule,referredReward,currency,"referral:"+id+":REFERRED",available,expires);state(id,order,hold==0?"QUALIFIED":"PENDING",available);}
 private void state(UUID id,UUID order,String state,Instant when){jdbc.update("UPDATE commerce.referral_attribution SET qualifying_order_id=?,state=?,qualify_after=?,version=version+1,updated_at=?,updated_by='reward-engine' WHERE id=? AND state='ATTRIBUTED'",order,state,when==null?null:Timestamp.from(when),Timestamp.from(clock.instant()),id);}
 private void append(UUID order,UUID correlation,UUID party,UUID rule,BigDecimal amount,String currency,String key,Instant available,int expiresDays){Instant expires=available.plusSeconds(expiresDays*86400L);UUID entry=EventCodec.uuid7(clock.instant());int inserted=jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,order_id,rule_id,kind,amount,currency_code,business_key,expires_at,available_at) VALUES (?,'reward-engine',?,?,?,'EARN',?,?,?, ?,?) ON CONFLICT(business_key) DO NOTHING",entry,party,order,rule,amount,currency,key,Timestamp.from(expires),Timestamp.from(available));if(inserted==1)audit.append("reward-engine",AuditValues.ActorKind.SYSTEM,AuditValues.Action.REWARD_ISSUE,AuditValues.Resource.REWARD,entry,correlation,AuditValues.Reason.VERIFIED_PROVIDER,null,Map.of("amount",amount.toPlainString(),"currency",currency),null);}
 @Override public void refundSettled(UUID refund,UUID correlation){tx();UUID order=jdbc.query("SELECT order_id FROM commerce.refund WHERE id=? AND state='SUCCEEDED'",(r,n)->r.getObject(1,UUID.class),refund).stream().findFirst().orElse(null);if(order==null)return;jdbc.query("SELECT id FROM commerce.sales_order WHERE id=? FOR UPDATE",(r,n)->r.getObject(1,UUID.class),order);var earns=jdbc.query("SELECT e.id,e.party_id,e.rule_id,e.amount,e.currency_code,e.expires_at,e.available_at,(SELECT coalesce(sum(ol.line_total-ol.tax_amount),0) FROM commerce.order_line ol WHERE ol.order_id=e.order_id) AS eligible_spend FROM commerce.reward_entry e WHERE e.order_id=? AND e.kind='EARN' ORDER BY e.id",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getBigDecimal(4),r.getString(5),r.getTimestamp(6)==null?null:r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant(),r.getBigDecimal(8)},order);BigDecimal refunded=jdbc.queryForObject("SELECT coalesce(sum(CASE WHEN ol.line_total>0 THEN rl.amount*(ol.line_total-ol.tax_amount)/ol.line_total ELSE 0 END),0) FROM commerce.refund_line rl JOIN commerce.refund r ON r.id=rl.refund_id JOIN commerce.order_line ol ON ol.id=rl.order_line_id WHERE r.order_id=? AND r.state='SUCCEEDED'",BigDecimal.class,order);if(refunded==null||refunded.signum()<=0)return;for(Object[] e:earns){if(e[5]!=null&&((Instant)e[5]).isBefore(clock.instant()))continue;BigDecimal base=(BigDecimal)e[7];if(base.signum()<=0)continue;UUID earning=(UUID)e[0],rule=(UUID)e[2];String mode=jdbc.queryForObject("SELECT parameters->>'refundMode' FROM commerce.promotion_rule WHERE id=?",String.class,rule);BigDecimal prior=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM commerce.reward_entry WHERE reverses_id=? AND kind='REVERSE'",BigDecimal.class,earning);int minor=jdbc.queryForObject("SELECT minor_unit FROM commerce.currency WHERE code=?",Integer.class,e[4]);BigDecimal original=(BigDecimal)e[3];BigDecimal target="FULL_ON_ANY_REFUND".equals(mode)?original:original.multiply(refunded).divide(base,12,RoundingMode.HALF_UP).setScale(minor,RoundingMode.HALF_UP);BigDecimal reverse=target.min(original).subtract(prior).max(BigDecimal.ZERO);if(reverse.signum()==0)continue;Instant available=((Instant)e[6]).isAfter(clock.instant())?(Instant)e[6]:clock.instant();String key="refund:"+refund+":reward:"+earning;UUID reversal=EventCodec.uuid7(clock.instant());int inserted=jdbc.update("INSERT INTO commerce.reward_entry(id,created_by,party_id,order_id,rule_id,kind,amount,currency_code,business_key,reverses_id,expires_at,available_at) VALUES (?,'reward-engine',?,?,?,'REVERSE',?,?,?,?,?,?) ON CONFLICT(business_key) DO NOTHING",reversal,e[1],order,rule,reverse,e[4],key,earning,e[5]==null?null:Timestamp.from((Instant)e[5]),Timestamp.from(available));if(inserted==1)audit.append("reward-engine",AuditValues.ActorKind.SYSTEM,AuditValues.Action.REWARD_ISSUE,AuditValues.Resource.REWARD,reversal,correlation,AuditValues.Reason.VERIFIED_PROVIDER,null,Map.of("amount",reverse.toPlainString(),"currency",e[4],"reverses",earning.toString()),null);}}
 @Override public void qualifyDue(){tx();var due=jdbc.query("SELECT id FROM commerce.referral_attribution WHERE state='PENDING' AND qualify_after<=? ORDER BY qualify_after,id FOR UPDATE SKIP LOCKED LIMIT 100",(r,n)->r.getObject(1,UUID.class),Timestamp.from(clock.instant()));for(UUID id:due){int changed=jdbc.update("UPDATE commerce.referral_attribution SET state='QUALIFIED',version=version+1,updated_at=?,updated_by='reward-engine' WHERE id=? AND state='PENDING' AND qualify_after<=?",Timestamp.from(clock.instant()),id,Timestamp.from(clock.instant()));if(changed==1)audit.append("reward-engine",AuditValues.ActorKind.SYSTEM,AuditValues.Action.REWARD_ISSUE,AuditValues.Resource.REFERRAL,id,EventCodec.uuid7(clock.instant()),AuditValues.Reason.RECONCILIATION,null,Map.of("qualified",true),null);}}
}
